/**
 * A library for rendering epub files
 *
 * The entry point is the {@link render} function, which takes an object iog
 * {@link RenderOptions}.
 *
 * @packageDocumentation
 */
import JsZip from "jszip";
import { v4 as uuid4 } from "uuid";
import { containerXml } from "./container.js";
import { contentOpf } from "./content.js";
import { getImageMimeExtension, getImageMimeType, isImageMimeType, } from "./image-mime.js";
import { nav } from "./nav.js";
import { section } from "./section.js";
import { tocNcx } from "./toc.js";
export { getImageMimeExtension, getImageMimeType, isImageMimeType };
/**
 * Render an epub from input content
 *
 * @returns a buffer of the generated epub
 */
export async function render({ title, author, publisher, copyright, subjects, description, uid = uuid4(), lang = "en", modified = new Date(), sections, images = new Map(), frames = new Map(), fonts = new Map(), css, missingImage = "error", }) {
    // create zip and write structural files
    const zip = new JsZip();
    zip.file("mimetype", "application/epub+zip");
    const metaInf = zip.folder("META-INF");
    metaInf.file("container.xml", containerXml());
    const oebps = zip.folder("OEBPS");
    const manifestItems = [];
    const tocItems = [];
    const remapping = new Map();
    // add images
    let iIdx = 0;
    for (const [src, { data, mime }] of images) {
        const id = `img_${iIdx++}`;
        const mediaType = mime ?? getImageMimeType(src);
        const ext = getImageMimeExtension(mediaType);
        const href = `images/${id}.${ext}`;
        oebps.file(href, data, { binary: true });
        remapping.set(src, href);
        manifestItems.push({
            id,
            href,
            mediaType,
            spine: false,
        });
    }
    // add frames
    let fIdx = 0;
    for (const [src, content] of frames) {
        const id = `frame_${fIdx++}`;
        const href = `frames/${id}.xhtml`;
        oebps.file(href, content);
        remapping.set(src, href);
        manifestItems.push({
            id,
            href,
            mediaType: "application/xhtml+xml",
            spine: false,
        });
    }
    // add fonts
    let tIdx = 0;
    for (const [name, data] of fonts) {
        const id = `font_${tIdx++}`;
        const href = `fonts/${name}`;
        oebps.file(href, data, { binary: true });
        manifestItems.push({ id, href, mediaType: "font/woff2", spine: false });
    }
    // add css
    let cssFile;
    if (css) {
        cssFile = "style.css";
        oebps.file(cssFile, css);
        manifestItems.push({
            id: "css",
            href: cssFile,
            mediaType: "text/css",
            spine: false,
        });
    }
    // add sections
    for (const [i, sect] of sections.entries()) {
        const id = `section_${i}`;
        const href = `${id}.xhtml`;
        const { title } = sect;
        oebps.file(href, section({ ...sect, lang, remapping, missingImage, cssFile }));
        manifestItems.push({
            id,
            href,
            mediaType: "application/xhtml+xml",
            spine: true,
        });
        tocItems.push({ id, title, href });
    }
    // add toc
    const tocFilename = "toc.ncx";
    oebps.file(tocFilename, tocNcx({ uid, title, author, lang, sections: tocItems }));
    manifestItems.push({
        id: "toc",
        href: tocFilename,
        mediaType: "application/x-dtbncx+xml",
        spine: false,
    });
    // add nav
    const navFilename = "nav.xhtml";
    oebps.file(navFilename, nav({ title, lang, sections: tocItems }));
    manifestItems.push({
        id: "nav",
        href: navFilename,
        mediaType: "application/xhtml+xml",
        properties: "nav",
        spine: false,
    });
    // add manifest
    // dcterms:modified must be CCYY-MM-DDThh:mm:ssZ, with no fractional seconds
    const modifiedIso = modified.toISOString().replace(/\.\d{3}Z$/, "Z");
    oebps.file("content.opf", contentOpf({
        title,
        author,
        publisher,
        copyright,
        subjects,
        description,
        lang,
        modified: modifiedIso,
        uid,
        content: manifestItems,
    }));
    return await zip.generateAsync({ type: "uint8array" });
}
